<script setup>
import { ref, onMounted, computed } from 'vue'
import useAgentStore from '@/stores/agents'
import bus from 'vue3-eventbus'
import ProgressSpinner from 'primevue/progressspinner'
import Avatar from 'primevue/avatar'
import { useRouter } from 'vue-router'
import useChatStore from '@/stores/chat'
import InputText from 'primevue/inputtext'

const router = useRouter()
const chatStore = useChatStore()
const emit = defineEmits(['close'])
const AgentStore = useAgentStore()

// 获取base URL
const baseUrl = import.meta.env.BASE_URL

const agents = ref([])
const loading = ref(false)
const searchQuery = ref('')

// 获取智能体列表
async function getAgentList() {
  loading.value = true
  try {
    const res = await AgentStore.fetchAgentList()
    agents.value = res.resData
  } catch (error) {
    console.error('获取智能体列表失败:', error)
  } finally {
    loading.value = false
  }
}

// 过滤后的智能体列表
const filteredAgents = computed(() => {
  const query = searchQuery.value.toLowerCase().trim()
  if (!query) return agents.value

  return agents.value.filter(
    (agent) => agent.name.toLowerCase().includes(query) || (agent.description && agent.description.toLowerCase().includes(query))
  )
})

// 选择智能体
async function selectAgent(agent) {
  // 发送事件，通知 Agent.vue 创建会话
  console.log('selectAgent called with:', agent)

  try {
    console.log('开始创建会话...')
    // 创建新会话
    const session = await chatStore.addConversation()

    if (session && session.id) {
      // 设置会话的智能体
      await AgentStore.setAssistant(session.id, agent.id)

      // 更新会话名称为智能体名称
      await chatStore.editConversationName(session.id, agent.name)

      // 设置为当前会话
      chatStore.currentConversationId = session.id

      console.log('会话创建成功，ID:', session.id)
      bus.emit('conversation:created', { type: 'agent' })

      //发送事件通知聊天页面切换会话
      bus.emit('conversation:change', session.id)
      console.log('Event emitted: conversation:change', session.id)

      // 导航到聊天页面
      router.push({ name: 'chat' })

      // 通过事件总线发送关闭对话框消息
      // 延迟发送关闭事件，确保路由跳转有时间完成
      setTimeout(() => {
        bus.emit('dialog:closeAgentList')
        emit('close')
        console.log('关闭对话框事件已发送')
      }, 300)

      return
    }
  } catch (error) {
    console.error('创建智能体会话失败:', error)
  }

  // 如果创建失败也尝试关闭对话框
  bus.emit('dialog:closeAgentList')
  emit('close')
}

onMounted(() => {
  getAgentList()
})
</script>

<template>
  <div class="agent-list">
    <!-- 搜索框 -->
    <div class="search-container">
      <div class="search-wrapper">
        <i class="pi pi-search search-icon"></i>
        <InputText v-model="searchQuery" placeholder="搜索助手" class="w-full search-input" />
      </div>
    </div>

    <div v-if="loading" class="flex justify-center items-center h-40">
      <ProgressSpinner />
    </div>
    <div v-else class="agent-list-container">
      <!-- 智能体列表 -->
      <div v-for="agent in filteredAgents" :key="agent.id" class="agent-item" @click="selectAgent(agent)">
        <div class="flex items-center">
          <Avatar
            :image="
              agent.avatar && !agent.avatar.startsWith('data:') && !agent.avatar.startsWith('http')
                ? baseUrl + agent.avatar.replace(/^\/open-chat/, '').replace(/^\//, '')
                : agent.avatar
            "
            shape="circle"
            size="normal"
            class="mr-3"
          />
          <div class="flex-1">
            <div class="font-semibold">{{ agent.name }}</div>
            <div class="text-sm text-gray-500">{{ agent.description }}</div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<style scoped>
.agent-list {
  background: white;
  border-radius: 8px;
  overflow: hidden;
  max-height: 400px;
  display: flex;
  flex-direction: column;
}

.search-container {
  padding: 12px 16px;
  border-bottom: 1px solid #e5e7eb;
  flex-shrink: 0;
}

.search-wrapper {
  position: relative;
  width: 100%;
}

.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #9ca3af;
  z-index: 1;
  pointer-events: none;
}

.search-container :deep(.p-inputtext) {
  padding: 8px 12px 8px 35px;
  font-size: 14px;
  border-radius: 6px;
  width: 100%;
}

.search-container :deep(.search-input::placeholder) {
  color: #9ca3af;
  font-size: 14px;
}

.agent-list-container {
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  overflow-y: auto;
  flex: 1;
}

/* 自定义滚动条样式 */
.agent-list-container::-webkit-scrollbar {
  width: 6px;
}

.agent-list-container::-webkit-scrollbar-track {
  background: #f1f1f1;
  border-radius: 3px;
}

.agent-list-container::-webkit-scrollbar-thumb {
  background: #d1d5db;
  border-radius: 3px;
}

.agent-list-container::-webkit-scrollbar-thumb:hover {
  background: #9ca3af;
}

.agent-item {
  padding: 10px 16px;
  border-bottom: 1px solid #e5e7eb;
  cursor: pointer;
  transition: all 0.2s ease;
}

.agent-item:last-child {
  border-bottom: none;
}

.agent-item:hover {
  background-color: #f9fafb;
}

:deep(.p-avatar) {
  width: 32px;
  height: 32px;
}
</style>
