<script setup>
import dayjs from 'dayjs'
import { useConfirm } from 'primevue/useconfirm'
import { i18nRender } from '@/locales'

const confirm = useConfirm()

const props = defineProps({
  name: {
    default: '',
    type: String
  },
  time: {
    default: 0,
    type: Number
  },
  avatar: {
    default: '',
    type: String
  },
  active: {
    default: false,
    type: Boolean
  },
  id: {
    default: '',
    type: [Number, String]
  },
  isAgent: {
    default: false,
    type: Boolean
  }
})

const emits = defineEmits(['editConversationName', 'deleteConversation', 'changeConversation', 'confirmChange'])

function changeConversation() {
  emits('changeConversation', props.id)
}

const editing = ref(false)
const editingName = ref('')

function editConversationName() {
  editing.value = true
  editingName.value = props.name
}

function cancelEdit() {
  editing.value = false
  editingName.value = ''
}

function deleteConversation(event) {
  confirm.require({
    target: event.currentTarget,
    message: i18nRender('lang.deleteConversationConfirm'),
    icon: 'pi pi-info-circle',
    rejectClass: 'p-button-secondary p-button-outlined p-button-sm',
    acceptClass: 'p-button-danger p-button-sm',
    rejectLabel: i18nRender('lang.cancel'),
    acceptLabel: i18nRender('lang.confirm'),
    accept: () => {
      emits('deleteConversation', props.id)
    },
    reject: () => {}
  })
}

function confirmChange() {
  emits('confirmChange', props.id, editingName.value)
  cancelEdit()
}
</script>

<template>
  <div
    class="history_item p-2 w-full rounded-xl cursor-pointer"
    :class="[active && 'bg-neutral-300 bg-opacity-40', !active && 'hover:bg-neutral-300 dark:hover:bg-blue-900']"
    @click="changeConversation"
  >
    <div class="flex flex-row items-center justify-start space-x-4">
      <!--      <Avatar class="shrink-0 grow-0" :label="avatar" shape="circle" style="background-color: #dee9fc; color: #1a2551" />-->
      <template v-if="!editing">
        <div class="name w-full shrink grow truncate font-bold text-slate-600 dark:text-slate-200 text-base">
          {{ name }}
        </div>
        <template v-if="!active">
          <div class="time w-14 shrink-0 grow-0 text-slate-400 dark:text-slate-400 text-sm text-end flex items-center justify-end">
            <span class="inline-block mr-1" :title="isAgent ? '智能体会话' : '普通会话'">
              <i :class="isAgent ? 'pi pi-star-fill text-yellow-500' : ''" style="font-size: 10px; opacity: 0.7"></i>
            </span>
            {{ dayjs(time).format('HH:mm') }}
          </div>
        </template>
        <template v-else>
          <div
            class="text-xl bg-transparent hover:bg-blue-100 hover:bg-opacity-50 dark:hover:bg-slate-700 p-2 rounded flex items-center justify-center border-none"
          >
            <!-- 编辑按钮 -->
            <button
              v-if="!isAgent"
              class="p-1 bg-transparent hover:bg-blue-100 hover:bg-opacity-50 dark:hover:bg-slate-700 rounded-full border-none flex items-center justify-center"
              @click.stop="editConversationName"
            >
              <i style="font-size: 12px" class="pi pi-pencil"></i>
            </button>
            <!-- 删除按钮 -->
            <button
              class="p-1 bg-transparent hover:bg-blue-100 hover:bg-opacity-50 dark:hover:bg-slate-700 rounded-full border-none flex items-center justify-center ml-1"
              @click="deleteConversation($event)"
            >
              <i style="font-size: 12px" class="pi pi-trash"></i>
            </button>
          </div>
        </template>
      </template>
      <template v-else>
        <InputText class="w-full shrink grow truncate font-bold text-slate-600 dark:text-slate-300" v-model="editingName"></InputText>
        <div
          class="action w-14 shrink-0 grow-0 text-slate-400 dark:text-slate-500 text-sm flex flex-row items-center justify-end space-x-1"
        >
          <div class="p-1" @click.stop="confirmChange">
            <i style="font-size: 12px" class="pi pi-check"></i>
          </div>
          <div class="p-1" @click.stop="cancelEdit">
            <i style="font-size: 12px" class="pi pi-times"></i>
          </div>
        </div>
      </template>
    </div>
  </div>
</template>

<style scoped lang="scss"></style>
