<script setup>
import ConversationItem from '@/views/chat/components/ConversationItem.vue'
import { i18nRender } from '@/locales'
import bus from 'vue3-eventbus'
import useAgentStore from '@/stores/agents'
import { onMounted, onBeforeUnmount, ref } from 'vue'

const agentStore = useAgentStore()
const activeTabIndex = ref(0)

// 在 setup 中添加初始化逻辑
onMounted(async () => {
  await agentStore.fetchAssistantList()

  // 添加会话创建事件监听
  bus.on('conversation:created', async ({ type }) => {
    await agentStore.fetchAssistantList()
    activeTabIndex.value = type === 'normal' ? 0 : 1
  })
})

onBeforeUnmount(() => {
  // 移除事件监听
  bus.off('conversation:created')
})

const props = defineProps({
  conversations: {
    type: Array,
    default: () => []
  },
  currentConversationId: {
    type: [Number, String],
    default: ''
  }
})

function groupByTimestamps(items) {
  const now = Date.now() // 获取当前时间的时间戳（毫秒）
  const oneDay = 24 * 60 * 60 * 1000 // 每天的毫秒数

  const groups = {
    today: { label: i18nRender('lang.today'), sessions: [] },
    last3Days: { label: i18nRender('lang.recent3day'), sessions: [] },
    last7Days: { label: i18nRender('lang.recent7day'), sessions: [] },
    last30Days: { label: i18nRender('lang.recent30day'), sessions: [] },
    earlier: { label: i18nRender('lang.earlier'), sessions: [] }
  }

  items.forEach((item) => {
    const timestamp = item.update_time // 直接使用13位的时间戳
    const diff = now - timestamp // 差值为毫秒数
    const daysDiff = diff / oneDay // 差值转换为天数

    if (daysDiff < 1) {
      groups.today.sessions.push(item)
    } else if (daysDiff < 3) {
      groups.last3Days.sessions.push(item)
    } else if (daysDiff < 7) {
      groups.last7Days.sessions.push(item)
    } else if (daysDiff < 30) {
      groups.last30Days.sessions.push(item)
    } else {
      groups.earlier.sessions.push(item)
    }
  })

  return groups
}

// 获取所有智能体的会话ID集合
const agentSessionIds = computed(() => {
  return new Set(agentStore.assistantList?.map((assistant) => assistant.session_id) || [])
})
const localConversations = computed(() => groupByTimestamps(props.conversations))
const normalConversations = computed(() => {
  return groupByTimestamps(props.conversations.filter((conv) => !agentSessionIds.value.has(conv.id)))
})

const agentConversations = computed(() => {
  return groupByTimestamps(props.conversations.filter((conv) => agentSessionIds.value.has(conv.id)))
})

// 添加 loading 状态
const isLoading = computed(() => agentStore.loading)

const route = useRoute()

async function changeConversation(id) {
  if (route.name !== 'chat') {
    await router.replace({ name: 'chat' })
  }
  if (id === props.currentConversationId) return
  // clearEditStatus()
  setTimeout(() => {
    bus.emit('conversation:change', id)
  }, 1)
}

async function createConversation() {
  console.log('createConversation')
  if (route.name !== 'chat') {
    await router.replace({ name: 'chat' })
  }
  bus.emit('conversation:created', { type: 'normal' })
  bus.emit('conversation:create')
}

function confirmChange(id, name) {
  bus.emit('conversation:rename', { id, name })
}

async function deleteConversation(id) {
  if (route.name !== 'chat') {
    await router.replace({ name: 'chat' })
  }
  bus.emit('conversation:delete', id)
}

const router = useRouter()

function goAssistant() {
  router.push({ name: 'assistant' })
}

const baseUrl = computed(() => import.meta.env.BASE_URL)
</script>

<template>
  <div class="history_container w-full h-full bg-transparent dark:bg-slate-800 pb-4 overflow-auto">
    <div class="h-full p-4 flex flex-col items-start justify-start">
      <div class="action mt-2 shrink-0 grow-0 flex flex-row items-center justify-around w-full space-x-6 mb-4">
        <Button @click="createConversation" class="w-full shrink" severity="contrast">
          <div class="flex items-center justify-center gap-1 w-full">
            <i class="pi pi-plus"></i>
            <span>
              {{ $t('lang.newChat') }}
            </span>
          </div>
        </Button>
      </div>
      <Button class="w-full" severity="secondary" @click="goAssistant">
        <div class="flex items-center justify-center gap-2 w-full">
          <img class="w-6 h-6" :src="`${baseUrl}icons/icon/ai-technology (2).png`" alt="" />
          <span>智能助手应用</span>
        </div>
      </Button>
      <div class="history_item_list space-y-4 w-full grow shrink h-full mt-4 overflow-y-auto">
        <TabView
          v-model:activeIndex="activeTabIndex"
          class="w-full h-full [&_.p-tabview-panels]:!bg-transparent [&_.p-tabview]:!bg-transparent [&_.p-tabview-panel]:!bg-transparent [&_.p-tabview-nav]:!bg-transparent [&_.p-tabview-nav-container]:!bg-transparent [&_.p-tabview-selected]:!bg-transparent [&_.p-tabview-nav-content]:!bg-transparent [&_.p-tabview-ink-bar]:!bg-transparent [&_::-webkit-scrollbar]:!bg-transparent [&_::-webkit-scrollbar-track]:!bg-transparent [&_::-webkit-scrollbar-thumb]:!bg-opacity-20 [&_::-webkit-scrollbar-thumb]:!bg-gray-400 [&_::-webkit-scrollbar-thumb]:!rounded-full"
        >
          <!-- 普通会话页签 -->
          <TabPanel header="普通会话">
            <template v-if="!isLoading">
              <template v-for="item in normalConversations" :key="item.label">
                <div class="text-slate-600 dark:text-slate-400 font-semibold ml-2 text-sm" v-if="item.sessions.length">
                  {{ item.label }}
                </div>
                <ConversationItem
                  v-for="session in item.sessions"
                  :name="session.session_name"
                  :time="session.update_time"
                  :active="session.id === currentConversationId"
                  :id="session.id"
                  :key="session.id"
                  :isAgent="agentSessionIds.has(session.id)"
                  @deleteConversation="deleteConversation"
                  @changeConversation="changeConversation"
                  @confirmChange="confirmChange"
                ></ConversationItem>
              </template>
            </template>
          </TabPanel>
          <!-- 智能体会话页签 -->
          <TabPanel header="智能体会话">
            <template v-if="!isLoading">
              <template v-for="item in agentConversations" :key="item.label">
                <div class="text-slate-600 dark:text-slate-400 font-semibold ml-2 text-sm" v-if="item.sessions.length">
                  {{ item.label }}
                </div>
                <ConversationItem
                  v-for="session in item.sessions"
                  :name="session.session_name"
                  :time="session.update_time"
                  :active="session.id === currentConversationId"
                  :id="session.id"
                  :key="session.id"
                  :isAgent="agentSessionIds.has(session.id)"
                  @deleteConversation="deleteConversation"
                  @changeConversation="changeConversation"
                  @confirmChange="confirmChange"
                ></ConversationItem>
              </template>
            </template>
          </TabPanel>
        </TabView>
      </div>
    </div>
  </div>
</template>

<style scoped lang="scss"></style>
