<script setup>
import { ref, onMounted } from 'vue'
import DataTable from 'primevue/datatable'
import Column from 'primevue/column'
import Button from 'primevue/button'
import Dialog from 'primevue/dialog'
import InputText from 'primevue/inputtext'
import Textarea from 'primevue/textarea'
import { getVersionList, versionUpdate, versionDelete, versionInsert } from '@/services/update'
import { useToast } from 'primevue/usetoast'
import Checkbox from 'primevue/checkbox'

const toast = useToast()
const activeTab = ref(0)
const showReleaseDialog = ref(false)
const isEdit = ref(false)
const editingVersion = ref(null)

const newVersion = ref({
  current_version: '',
  last_version: '',
  release_time: new Date().toISOString().split('T')[0],
  release_log: '',
  is_release: false
})

// 版本列表数据
const versions = ref([])
const loading = ref(false)

// 获取版本列表
async function fetchVersionList() {
  try {
    loading.value = true
    const res = await getVersionList()
    console.log(res)
    const version_list = JSON.parse(res.resData)
    if (version_list && Array.isArray(version_list)) {
      // 清空当前版本列表
      versions.value = []
      // 遍历所有版本信息
      version_list.forEach((version) => {
        versions.value.push({
          last_version: version.last_version || '',
          current_version: version.current_version || '',
          release_time: version.release_time || '',
          release_log: version.release_log || '',
          is_release: version.is_release
        })
      })
    }
  } catch (error) {
    console.error('获取版本列表失败:', error)
  } finally {
    loading.value = false
  }
}

// 编辑版本
function editVersion(version) {
  console.log('editVersion')
  isEdit.value = true
  editingVersion.value = { ...version }
  newVersion.value = {
    current_version: version.current_version,
    last_version: version.last_version,
    release_time: version.release_time,
    release_log: version.release_log,
    is_release: version.is_release
  }
  showReleaseDialog.value = true
}

// 删除版本
async function deleteVersion(version) {
  if (confirm('确定要删除这个版本吗？')) {
    try {
      loading.value = true
      await versionDelete({
        current_version: version.current_version,
        last_version: version.last_version
      })

      const index = versions.value.findIndex(
        (v) => v.current_version === version.current_version && v.last_version === version.last_version
      )
      if (index > -1) {
        versions.value.splice(index, 1)
        toast.add({
          severity: 'success',
          summary: '成功',
          detail: '版本已删除',
          life: 3000
        })
      }
    } catch (error) {
      console.error('删除版本失败:', error)
      toast.add({
        severity: 'error',
        summary: '错误',
        detail: '删除版本失败',
        life: 3000
      })
    } finally {
      loading.value = false
    }
  }
}

// 添加或更新版本
async function addNewVersion() {
  if (!newVersion.value.current_version || !newVersion.value.release_log) {
    toast.add({
      severity: 'error',
      summary: '错误',
      detail: '请填写完整信息',
      life: 3000
    })
    return
  }

  try {
    loading.value = true
    const versionData = {
      last_version: newVersion.value.last_version,
      current_version: newVersion.value.current_version,
      release_time: newVersion.value.release_time || new Date().toISOString().split('T')[0],
      release_log: newVersion.value.release_log,
      is_release: newVersion.value.is_release
    }

    if (isEdit.value) {
      // 更新版本
      const updateData = {
        last_version: editingVersion.value.last_version, // 原上一版本号
        current_version: editingVersion.value.current_version, // 当前版本号
        release_time: versionData.release_time,
        release_log: versionData.release_log,
        is_release: versionData.is_release
      }

      await versionUpdate(updateData)

      // 更新本地数据
      const index = versions.value.findIndex(
        (v) => v.current_version === editingVersion.value.current_version && v.last_version === editingVersion.value.last_version
      )
      if (index > -1) {
        versions.value[index] = { ...versionData }
        toast.add({
          severity: 'success',
          summary: '成功',
          detail: '版本已更新',
          life: 3000
        })
      }
    } else {
      // 添加新版本
      await versionInsert(versionData)
      versions.value.unshift(versionData)
      toast.add({
        severity: 'success',
        summary: '成功',
        detail: '新版本已添加',
        life: 3000
      })
    }

    closeDialog()
  } catch (error) {
    console.error(isEdit.value ? '更新版本失败:' : '添加版本失败:', error)
    toast.add({
      severity: 'error',
      summary: '错误',
      detail: isEdit.value ? '更新版本失败' : '添加版本失败',
      life: 3000
    })
  } finally {
    loading.value = false
  }
}

// 关闭对话框
function closeDialog() {
  showReleaseDialog.value = false
  isEdit.value = false
  editingVersion.value = null
  newVersion.value = {
    current_version: '',
    last_version: '',
    release_time: new Date().toISOString().split('T')[0],
    release_log: '',
    is_release: false
  }
}

const adminMenus = [{ label: '版本发布', icon: 'pi pi-tag' }]

onMounted(() => {
  fetchVersionList()
})
</script>

<template>
  <div class="admin-container p-4">
    <div class="header mb-4 flex justify-between items-center">
      <h2 class="text-xl font-bold">管理员控制台</h2>
      <Button icon="pi pi-plus" label="发布新版本" severity="success" @click="showReleaseDialog = true" />
    </div>

    <div class="content flex">
      <!-- 左侧菜单 -->
      <div class="menu w-48 bg-gray-50 rounded-lg p-2">
        <div
          v-for="(menu, index) in adminMenus"
          :key="index"
          class="menu-item flex items-center gap-2 p-3 rounded cursor-pointer transition-colors"
          :class="activeTab === index ? 'bg-blue-50 text-blue-600' : 'hover:bg-gray-100'"
          @click="activeTab = index"
        >
          <i :class="menu.icon"></i>
          <span>{{ menu.label }}</span>
        </div>
      </div>

      <!-- 右侧内容区 -->
      <div class="content-area flex-1 ml-4 bg-white rounded-lg p-4">
        <div v-if="activeTab === 0">
          <h3 class="text-lg font-semibold mb-4">版本管理</h3>
          <DataTable :value="versions" stripedRows :loading="loading">
            <Column field="last_version" header="上一版本">
              <template #body="slotProps">
                <div class="flex items-center gap-2">
                  {{ slotProps.data.last_version }}
                </div>
              </template>
            </Column>
            <Column field="current_version" header="最新版本">
              <template #body="slotProps">
                <div class="flex items-center gap-2">
                  {{ slotProps.data.current_version }}
                </div>
              </template>
            </Column>
            <Column field="release_time" header="发布时间"></Column>
            <Column field="release_log" header="更新内容">
              <template #body="slotProps">
                <div class="whitespace-pre-wrap">{{ slotProps.data.release_log }}</div>
              </template>
            </Column>
            <Column field="is_release" header="是否发布">
              <template #body="slotProps">
                <div class="flex items-center">
                  <span
                    :class="[
                      'px-2 py-1 rounded text-sm',
                      slotProps.data.is_release ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-600'
                    ]"
                  >
                    {{ slotProps.data.is_release ? '已发布' : '未发布' }}
                  </span>
                </div>
              </template>
            </Column>
            <Column header="操作" :style="{ width: '150px' }">
              <template #body="slotProps">
                <div class="flex gap-2">
                  <Button icon="pi pi-pencil" severity="info" text rounded @click="editVersion(slotProps.data)" />
                  <Button icon="pi pi-trash" severity="danger" text rounded @click="deleteVersion(slotProps.data)" />
                </div>
              </template>
            </Column>
          </DataTable>
        </div>
      </div>
    </div>

    <!-- 编辑版本或发布新版本对话框 -->
    <Dialog
      v-model:visible="showReleaseDialog"
      :modal="true"
      :header="isEdit ? '编辑版本' : '发布新版本'"
      :style="{ width: '500px' }"
      @hide="closeDialog"
    >
      <div class="flex flex-col gap-4 p-2">
        <div class="field">
          <label class="block mb-2">最新版本</label>
          <InputText v-model="newVersion.current_version" :disabled="isEdit" class="w-full" placeholder="例如: v1.0.0" />
        </div>
        <div class="field">
          <label class="block mb-2">上一版本</label>
          <InputText v-model="newVersion.last_version" :disabled="isEdit" class="w-full" placeholder="例如: v0.9.0" />
        </div>
        <div class="field">
          <label class="block mb-2">更新内容</label>
          <Textarea v-model="newVersion.release_log" rows="5" class="w-full" placeholder="请输入本次更新的主要内容..." />
        </div>
        <div class="field flex items-center gap-2">
          <Checkbox v-model="newVersion.is_release" :binary="true" />
          <label>是否发布</label>
        </div>
      </div>
      <template #footer>
        <Button label="取消" severity="secondary" @click="closeDialog" class="mr-2" />
        <Button :label="isEdit ? '保存' : '发布'" @click="addNewVersion" />
      </template>
    </Dialog>
  </div>
</template>

<style scoped>
.admin-container {
  min-height: 500px;
}

.menu-item {
  font-size: 0.95rem;
}

.menu-item i {
  font-size: 1.1rem;
}

:deep(.p-datatable) {
  font-size: 0.9rem;
}

.whitespace-pre-wrap {
  white-space: pre-wrap;
}

:deep(.p-button.p-button-icon-only) {
  width: 2rem;
  height: 2rem;
}
</style>
