<script setup>
import useAppStore from '@/stores/app'
import useModelStore from '@/stores/models'
import useChatStore from '@/stores/chat'
import useAgentStore from '@/stores/agents'
import ConversationList from '@/views/chat/components/ConversationList.vue'
import { useDialog } from 'primevue/usedialog'
import ApiKey from '@/components/ApiKey/ApiKey.vue'
import WhatsNew from '@/components/WhatsNew.vue'
import AgentList from '@/views/agent/components/AgentList.vue'
import bus from 'vue3-eventbus'
import TranslatedfileList from '@/views/translate/TranslatedfileList.vue'
import { getTranslatedFileHistory } from '@/services/translate'
import Admin from '@/views/admin/Admin.vue'
import Password from 'primevue/password'
import { useToast } from 'primevue/usetoast'
import { exitImmediately, eventBus, checkDownloadStatus } from '@/services/update'
const taskId = ref(null)
const showUpdateButton = ref(false)
const showRestartDialog = ref(false)

const dialog = useDialog()
const toast = useToast()

const app = useAppStore()
const ModelStore = useModelStore()
const ChatStore = useChatStore()
const AgentStore = useAgentStore()

// 对话列表
const conversations = computed(() => ChatStore.conversations)
const currentConversationId = computed(() => ChatStore.currentConversationId)
const init = async () => {
  console.log('init')
  try {
    // 初始化对话和对话内容表
    await initConversations()
  } catch (error) {
    console.error('Error initializing tables:', error)
  }
}

const initConversations = async () => {
  await ChatStore.getConversationList()

  // 如果对话表为空，则创建一个示例对话
  if (conversations.value.length === 0) {
    // 将示例对话插入对话表
    await ChatStore.addConversation()
    // 更新对话列表
    await ChatStore.getConversationList()
  }

  // 更新当前对话id为第一条对话
  ChatStore.currentConversationId = conversations.value[0].id
}

init()

const leftCollapsed = computed(() => {
  return app.conversationCollapsed
})

// const leftCollapsed = ref(false)
// const rightCollapsed = ref(false)
function initModel() {
  Promise.allSettled([ModelStore.getModelList(), ModelStore.getLoadedModel()])
}

initModel()

function showApiKeys() {
  dialog.open(ApiKey, {
    props: {
      header: '添加API Key',
      modal: true,
      style: {
        width: '600px'
      }
    }
  })
}

onMounted(() => {
  bus.on('showApiKeys', showApiKeys)
})

function showWhatsNew() {
  console.log('showWhatsNew')
  dialog.open(WhatsNew, {
    props: {
      modal: true,
      style: {
        width: '640px'
      }
    }
  })
}

function checkIsFirst() {
  const hasOpened = localStorage.getItem('hasOpened')
  console.log(hasOpened)
  if (!hasOpened) {
    localStorage.setItem('hasOpened', 'true')
    showWhatsNew()
  } else {
    // showWhatsNew()
  }
}

checkIsFirst()

function handleStartUpdate({ taskId: newId }) {
  showUpdateButton.value = true
  taskId.value = newId
  console.log('🟢 收到更新任务：', taskId.value)
}

onMounted(() => {
  bus.on('showWhatsNew', showWhatsNew)
  bus.on('refreshFileHistory', loadFileHistory)
  eventBus.on('start-update', handleStartUpdate)
  downloadPolling()
  if (isTranslateMode.value) {
    startPolling()
  }
})

onUnmounted(() => {
  stopPolling()
  eventBus.off('start-update', handleStartUpdate)
})

const router = useRouter()
function goAgent() {
  isTranslateMode.value = false
  router.push({ name: 'agent' })
}
function goKnowledge() {
  isTranslateMode.value = false
  router.push({ name: 'knowledge' })
}
function goSetting() {
  isTranslateMode.value = false
  router.push({ name: 'setting' })
}
function onClick() {
  alert('正在下载新版本，请不要退出应用！')
}
// 显示智能体列表对话框
function showAgentList() {
  const dialogRef = dialog.open(AgentList, {
    props: {
      header: '选择智能体',
      modal: true,
      style: {
        width: '600px'
      },
      onClose: () => {
        console.log('AgentList dialog closed')
      }
    }
  })

  // 监听自定义关闭事件
  bus.on('dialog:closeAgentList', () => {
    console.log('收到关闭AgentList对话框事件')
    setTimeout(() => {
      dialogRef.close()
      bus.off('dialog:closeAgentList')
    }, 100)
  })
}
const isTranslateMode = ref(false)
const fileHistory = ref([])

let pollInterval

async function loadFileHistory() {
  const res = await getTranslatedFileHistory()
  if (res.resData && JSON.stringify(res.resData) !== JSON.stringify(fileHistory.value)) {
    fileHistory.value = res.resData
  }
}

async function handleRestart() {
  try {
    await exitImmediately()
  } catch (error) {
    console.error('重启应用失败:', error)
    toast.add({
      severity: 'error',
      summary: '重启失败',
      detail: '应用重启失败，请手动重启应用',
      life: 5000
    })
  }
  showRestartDialog.value = false
}

let downloadStatusInterval = null
function downloadPolling() {
  // ✅ 每 5 秒轮询一次下载状态
  downloadStatusInterval = setInterval(async () => {
    //未生成下载任务直接跳过
    if (!taskId.value || !showUpdateButton.value) {
      eventBus.emit('downloadable', { taskId: taskId.value })
    }

    if (showUpdateButton.value && taskId.value) {
      try {
        const res = await checkDownloadStatus({ task_id: taskId.value })
        const { status } = JSON.parse(res.resData)

        console.log('📦 下载状态:', status)

        if (status === true) {
          showUpdateButton.value = false
          showRestartDialog.value = true
          clearInterval(downloadStatusInterval)
          console.log('✅ 下载完成')

          // ✅ 通知其他组件
          eventBus.emit('download-complete', { taskId: taskId.value })
        }
      } catch (e) {
        console.error('❌ 下载状态检查失败:', e)
      }
    }
  }, 3000)
}

function startPolling() {
  // ✅ 每 2 秒轮询一次文件历史
  pollInterval = setInterval(loadFileHistory, 2000)
}

function stopPolling() {
  if (pollInterval) {
    clearInterval(pollInterval)
    pollInterval = null
  }
}

function goTranslate() {
  if (isTranslateMode.value) {
    router.push({ name: 'chat' })
    isTranslateMode.value = false
    stopPolling()
  } else {
    router.push({ name: 'translate' })
    isTranslateMode.value = true
    loadFileHistory()
    startPolling()
  }
}

// 添加管理员对话框控制
const showAdminDialog = ref(false)
const adminPassword = ref('')
const showPasswordDialog = ref(false)

// 启动管理员功能
function openAdminPanel() {
  showPasswordDialog.value = false
}

function verifyPassword() {
  // 这里可以改为实际的密码验证逻辑
  const correctPassword = '991128,.'

  if (adminPassword.value === correctPassword) {
    showPasswordDialog.value = false
    adminPassword.value = '' // 清空密码

    // 打开管理员面板
    dialog.open(Admin, {
      props: {
        header: '管理员控制台',
        modal: true,
        style: {
          width: '80vw',
          maxWidth: '1200px'
        },
        maximizable: true
      }
    })
  } else {
    toast.add({
      severity: 'error',
      summary: '错误',
      detail: '密码错误，请重试',
      life: 3000
    })
  }
}
</script>

<template>
  <!--  <div class="loading w-screen h-screen fixed z-50 backdrop-blur-sm">-->
  <!--    <div class="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center justify-center space-y-6">-->
  <!--      <ProgressSpinner class="" />-->
  <!--      <span class="text-center text-xl text-slate-900 dark:text-slate-50 font-bold tracking-widest">{{ $t('lang.loading') }}...</span>-->
  <!--    </div>-->
  <!--  </div>-->
  <div class="w-screen h-screen chat shrink grow flex flex-row items-center justify-start overflow-auto bg-neutral-200">
    <Button v-if="showUpdateButton" class="floating-button" @click="onClick">更新中…</Button>
    <div
      class="shrink-0 grow-0 h-full flex flex-col items-start justify-start overflow-hidden transition-all duration-200"
      :class="leftCollapsed ? ['w-0'] : ['w-[260px]']"
    >
      <div class="text-2xl text-center w-full font-bold font-sans pt-6 pb-0 flex items-center justify-center gap-2">
        <img
          src="/icons/logo-transparent.png"
          alt="OpenChat Logo"
          class="w-40 h-15 cursor-pointer hover:opacity-80 transition-opacity"
          @click="openAdminPanel"
        />
        <!-- <span>OpenChat</span> -->
      </div>
      <div class="flex flex-col h-[calc(100%-260px)] overflow-y-auto w-full">
        <template v-if="!isTranslateMode">
          <ConversationList class="shrink-0" :conversations="conversations" :currentConversationId="currentConversationId" />
        </template>
        <template v-else>
          <TranslatedfileList class="shrink-0" :filehistory="fileHistory" />
        </template>
      </div>
      <div class="w-full py-2 px-4 flex flex-col gap-2 mt-auto">
        <div class="w-full flex items-center justify-between gap-4 shrink-0 grow-0 flex-nowrap">
          <Button icon="pi pi-users" class="w-full shrink grow" severity="secondary" label="我的搭档" @click="goAgent"></Button>
          <Button icon="pi pi-plus" class="w-full shrink grow" severity="secondary" label="添加助手" @click="showAgentList"></Button>
        </div>
        <div class="w-full flex items-center justify-between gap-4 shrink-0 grow-0 flex-nowrap">
          <Button
            icon="pi pi-comment"
            class="w-full shrink grow"
            severity="secondary"
            :label="isTranslateMode ? '返回对话' : 'AI翻译'"
            @click="goTranslate"
          ></Button>
        </div>
        <div class="w-full flex items-center justify-between gap-4 shrink-0 grow-0 flex-nowrap">
          <Button icon="pi pi-book" class="w-full shrink grow" severity="secondary" label="配置知识库" @click="goKnowledge"></Button>
        </div>
        <div class="w-full flex items-center justify-between gap-4 shrink-0 grow-0 flex-nowrap">
          <Button icon="pi pi-key" class="w-full shrink grow" severity="secondary" label="添加API" @click="showApiKeys"></Button>
          <Button icon="pi pi-cog" class="w-full shrink grow" severity="secondary" label="设置" @click="goSetting"></Button>
        </div>
      </div>
    </div>
    <RouterView v-slot="{ Component }">
      <KeepAlive>
        <Component v-if="route?.meta.keepAlive" :is="Component"></Component>
      </KeepAlive>
      <Component v-if="!route?.meta.keepAlive" :is="Component"></Component>
    </RouterView>

    <!-- 添加密码验证对话框 -->
    <Dialog v-model:visible="showPasswordDialog" modal :closable="true" :style="{ width: '400px' }" header="管理员验证">
      <div class="flex flex-col gap-4 p-4">
        <div class="text-sm text-gray-600">请输入管理员密码以继续：</div>
        <Password v-model="adminPassword" :feedback="false" toggleMask class="w-full" @keyup.enter="verifyPassword" />
        <div class="flex justify-end gap-2">
          <Button label="取消" severity="secondary" @click="showPasswordDialog = false" />
          <Button label="确认" @click="verifyPassword" />
        </div>
      </div>
    </Dialog>

    <Dialog
      v-model:visible="showRestartDialog"
      modal
      :closable="false"
      :pt="{
        root: { class: 'restart-dialog' }
      }"
    >
      <template #header>
        <div class="flex align-items-center gap-2">
          <i class="pi pi-check-circle text-success text-xl"></i>
          <span class="text-xl font-semibold">更新下载完成</span>
        </div>
      </template>
      <div class="update-success-content">
        <p>新版本已经下载完成，需要重启应用以完成更新。</p>
        <p class="text-sm text-500">建议立即重启以体验新功能。</p>
      </div>
      <template #footer>
        <div class="flex gap-2 justify-content-end">
          <!-- <Button label="稍后重启" severity="secondary" @click="showRestartDialog = false" /> -->
          <Button label="立即重启" severity="success" @click="handleRestart" />
        </div>
      </template>
    </Dialog>
  </div>
</template>

<style scoped lang="scss">
.floating-button {
  position: fixed;
  bottom: 20px;
  right: 20px;
  padding: 10px 20px;
  background-color: #c8f9cc; /* ✅ 浅绿色背景 */
  color: #333;
  border: none;
  border-radius: 8px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.15);
  z-index: 9999;
  cursor: pointer;
  opacity: 0.8;
  transition: all 0.3s ease;
}

.floating-button:hover {
  opacity: 1;
}
.file-panel {
  .file-title {
    overflow: hidden;
    white-space: nowrap;
    word-break: break-all;
    text-overflow: ellipsis;
    max-width: 200px;
  }

  ::v-deep(.p-toggleable-content) {
    height: calc(100% - 65px);
  }

  ::v-deep(.p-panel-content) {
    height: 100%;
  }
}

.tabs_container {
  position: absolute;
  top: 10px;
  left: -5px;
  display: flex;
  flex-direction: column;
  z-index: 1;
  padding-top: 20px;
}

.tabs-item {
  width: 40px;
  height: 120px;
  margin: -10px 10px 0 0;
  border-radius: 15px 0 0 15px;
  writing-mode: vertical-lr;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.tabs-item-active {
  z-index: 99 !important;
}

:deep(.p-password input) {
  width: 100%;
}
</style>
